import{_ as e}from"./chunks/projects.BdG50VF9.js";import{_ as o,c as r,o as i,a2 as s}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Antes de confirmar los cambios","description":"Revise cada archivo modificado en una carpeta de proyecto y confirme los cambios sin salir de qDiff.","frontmatter":{"title":"Antes de confirmar los cambios","description":"Revise cada archivo modificado en una carpeta de proyecto y confirme los cambios sin salir de qDiff."},"headers":[],"relativePath":"es/guide/projects.md","filePath":"es/guide/projects.md","lastUpdated":1794296122000}'),n={name:"es/guide/projects.md"};function t(c,a,l,d,m,p){return i(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="antes-de-confirmar-los-cambios" tabindex="-1">Antes de confirmar los cambios <a class="header-anchor" href="#antes-de-confirmar-los-cambios" aria-label="Permalink to &quot;Antes de confirmar los cambios&quot;">​</a></h1><p>Vale la pena hacerse la rápida pregunta «¿qué cambié en realidad?» antes de cada confirmación. Abra una carpeta de proyecto en qDiff y la respuesta ya está desplegada ante usted.</p><img src="'+e+'" alt="Una lista de archivos modificados junto a una comparación coloreada" class="guide-shot"><h2 id="abra-una-carpeta-de-proyecto" tabindex="-1">Abra una carpeta de proyecto <a class="header-anchor" href="#abra-una-carpeta-de-proyecto" aria-label="Permalink to &quot;Abra una carpeta de proyecto&quot;">​</a></h2><p>Elija la carpeta de un proyecto Git desde <strong>Archivo → Abrir</strong> o arrástrela a la ventana. qDiff reúne en una sola lista los archivos que ha tocado.</p><h2 id="lea-la-lista-y-luego-los-cambios" tabindex="-1">Lea la lista y luego los cambios <a class="header-anchor" href="#lea-la-lista-y-luego-los-cambios" aria-label="Permalink to &quot;Lea la lista y luego los cambios&quot;">​</a></h2><p>Cada archivo aparece marcado según lo que le ocurrió: nuevo, modificado o eliminado. Haga clic en uno y el lado derecho muestra exactamente qué cambió en su interior, con los mismos colores y resaltados por palabra que en una comparación de archivos normal.</p><p>Recórralos uno a uno: la lista recuerda por dónde iba, para que no se salte nada en una revisión larga.</p><h2 id="termine-en-la-misma-ventana" tabindex="-1">Termine en la misma ventana <a class="header-anchor" href="#termine-en-la-misma-ventana" aria-label="Permalink to &quot;Termine en la misma ventana&quot;">​</a></h2><p>Cuando todo esté en orden, confirme los cambios desde aquí. También puede actualizar, enviar los cambios, revertir o resolver un conflicto sin salir de la comparación. No necesita tener abierta ninguna otra aplicación ni crear una cuenta.</p><div class="tip custom-block"><p class="custom-block-title">¿No es una carpeta de proyecto?</p><p>Cualquier carpeta corriente se abre igualmente como una comparación de carpetas normal: <a href="./folders.html">comparar carpetas</a> funciona en todas partes.</p></div><p>A continuación: <a href="./more.html">imágenes, archivos comprimidos y más</a>.</p>',12)])])}const b=o(n,[["render",t]]);export{h as __pageData,b as default};
